	private final ResolutionModelElements pResolutionModel;
	private final ResolutionElements pResolution;
	private final FunctionalMappingElements pFunctionalMapping;
	private final FeatureReferenceElements pFeatureReference;
	private final ImportElements pImport;
	private final ReconfigurationElements pReconfiguration;
	private final SetParamElements pSetParam;
	private final SetLifecycleElements pSetLifecycle;
	private final LifecycleStateElements eLifecycleState;
	private final TerminalRule tWS;
	
	private final Grammar grammar;
	
	private final BasicsGrammarAccess gaBasics;
	
	private final TerminalsGrammarAccess gaTerminals;

	@Inject
	public ResolutionModelGrammarAccess(GrammarProvider grammarProvider,
			BasicsGrammarAccess gaBasics,
			TerminalsGrammarAccess gaTerminals) {
		this.grammar = internalFindGrammar(grammarProvider);
		this.gaBasics = gaBasics;
		this.gaTerminals = gaTerminals;
		this.pResolutionModel = new ResolutionModelElements();
		this.pResolution = new ResolutionElements();
		this.pFunctionalMapping = new FunctionalMappingElements();
		this.pFeatureReference = new FeatureReferenceElements();
		this.pImport = new ImportElements();
		this.pReconfiguration = new ReconfigurationElements();
		this.pSetParam = new SetParamElements();
		this.pSetLifecycle = new SetLifecycleElements();
		this.eLifecycleState = new LifecycleStateElements();
		this.tWS = (TerminalRule) GrammarUtil.findRuleForName(getGrammar(), "eu.coresense.resolution.ResolutionModel.WS");
	}
	
	protected Grammar internalFindGrammar(GrammarProvider grammarProvider) {
		Grammar grammar = grammarProvider.getGrammar(this);
		while (grammar != null) {
			if ("eu.coresense.resolution.ResolutionModel".equals(grammar.getName())) {
				return grammar;
			}
			List<Grammar> grammars = grammar.getUsedGrammars();
			if (!grammars.isEmpty()) {
				grammar = grammars.iterator().next();
			} else {
				return null;
			}
		}
		return grammar;
	}
	
	@Override
	public Grammar getGrammar() {
		return grammar;
	}
	
	
	public BasicsGrammarAccess getBasicsGrammarAccess() {
		return gaBasics;
	}
	
	public TerminalsGrammarAccess getTerminalsGrammarAccess() {
		return gaTerminals;
	}

	
